# ── Bull/Bear phases ──────────────────────────────────────────────────────
# Identify major phases using 200-day moving average crossovers simplified
# We'll use a simpler approach: significant peaks and troughs
def identify_phases(data, threshold=0.30):
    phases = []
    peak = data[0]['close']
    trough = data[0]['close']
    peak_date = data[0]['date_str']
    trough_date = data[0]['date_str']
    in_bull = True
    last_pivot_date = data[0]['date_str']
    last_pivot_price = data[0]['close']

    for r in data:
        if in_bull:
            if r['close'] > peak:
                peak = r['close']
                peak_date = r['date_str']
            elif (r['close'] - peak) / peak < -threshold:
                phases.append({'type': 'Bull', 'start': last_pivot_date, 'end': peak_date,
                             'start_price': last_pivot_price, 'end_price': peak,
                             'return': (peak / last_pivot_price - 1) * 100})
                in_bull = False
                trough = r['close']
                trough_date = r['date_str']
                last_pivot_date = peak_date
                last_pivot_price = peak
        else:
            if r['close'] < trough:
                trough = r['close']
                trough_date = r['date_str']
            elif (r['close'] - trough) / trough > threshold:
                phases.append({'type': 'Bear', 'start': last_pivot_date, 'end': trough_date,
                             'start_price': last_pivot_price, 'end_price': trough,
                             'return': (trough / last_pivot_price - 1) * 100})
                in_bull = True
                peak = r['close']
                peak_date = r['date_str']
                last_pivot_date = trough_date
                last_pivot_price = trough

    phases.append({'type': 'Bull' if in_bull else 'Bear', 'start': last_pivot_date, 'end': data[-1]['date_str'],
                 'start_price': last_pivot_price, 'end_price': data[-1]['close'],
                 'return': (data[-1]['close'] / last_pivot_price - 1) * 100})
    return phases

