# Sub-period CAGRs
def compute_cagr(data, start_year, end_year):
    subset = [r for r in data if start_year <= r['date'].year <= end_year]
    if len(subset) < 2:
        return None
    s = subset[0]['close']
    e = subset[-1]['close']
    y = (subset[-1]['date'] - subset[0]['date']).days / 365.25
    if y < 0.5 or s <= 0:
        return None
    return (pow(e / s, 1.0 / y) - 1) * 100

