        date_str = r['Date'][:10]
        dt = datetime.strptime(date_str, '%Y-%m-%d')
        rows.append({
            'date': dt,
            'date_str': date_str,
            'open': float(r['Open']),
            'high': float(r['High']),
            'low': float(r['Low']),
            'close': float(r['Close']),
            'volume': int(r['Volume']),
            'dividend': float(r['Dividends']),
            'split': float(r['Stock Splits']),
        })

