first_close = rows[0]['close']
last_close = rows[-1]['close']
total_days = len(rows)
years = (last_date - first_date).days / 365.25

# KPIs
cumulative_return = (last_close / first_close - 1) * 100
cagr = (pow(last_close / first_close, 1.0 / years) - 1) * 100

# Max Drawdown
peak = rows[0]['close']
max_dd = 0
max_dd_peak_date = rows[0]['date_str']
max_dd_trough_date = rows[0]['date_str']
dd_peak_date = rows[0]['date_str']
drawdowns = []
current_dd_start = rows[0]['date_str']

for r in rows:
    if r['close'] > peak:
        peak = r['close']
        dd_peak_date = r['date_str']
    dd = (r['close'] - peak) / peak
    if dd < max_dd:
        max_dd = dd
        max_dd_peak_date = dd_peak_date
        max_dd_trough_date = r['date_str']

max_dd_pct = max_dd * 100

# Annualized Volatility
