# ── Identify major drawdown episodes ──────────────────────────────────────
def find_drawdowns(data, top_n=5):
    episodes = []
    peak_val = data[0]['close']
    peak_idx = 0
    current_trough = data[0]['close']
    trough_idx = 0
    in_drawdown = False

    for i, r in enumerate(data):
        if r['close'] >= peak_val:
            if in_drawdown and (current_trough / peak_val - 1) < -0.15:
                episodes.append({
                    'peak_date': data[peak_idx]['date_str'],
                    'trough_date': data[trough_idx]['date_str'],
                    'peak_val': peak_val,
                    'trough_val': current_trough,
                    'drawdown': (current_trough / peak_val - 1) * 100,
                    'recovery_date': r['date_str'],
                })
            peak_val = r['close']
            peak_idx = i
            current_trough = r['close']
            trough_idx = i
            in_drawdown = False
        elif r['close'] < current_trough:
            current_trough = r['close']
            trough_idx = i
            in_drawdown = True

    if in_drawdown and (current_trough / peak_val - 1) < -0.15:
        episodes.append({
            'peak_date': data[peak_idx]['date_str'],
            'trough_date': data[trough_idx]['date_str'],
            'peak_val': peak_val,
            'trough_val': current_trough,
            'drawdown': (current_trough / peak_val - 1) * 100,
            'recovery_date': 'N/A',
        })

    episodes.sort(key=lambda x: x['drawdown'])
    return episodes[:top_n]

