    if not decade_rows:
        continue

    d_first = decade_rows[0]['close']
    d_last = decade_rows[-1]['close']
    d_return = (d_last / d_first - 1) * 100
    d_years = max((decade_rows[-1]['date'] - decade_rows[0]['date']).days / 365.25, 0.5)
    d_cagr = (pow(d_last / d_first, 1.0 / d_years) - 1) * 100

    d_returns = []
    for i in range(1, len(decade_rows)):
        if decade_rows[i-1]['close'] > 0:
            d_returns.append((decade_rows[i]['close'] - decade_rows[i-1]['close']) / decade_rows[i-1]['close'])

    d_vol = 0
    if d_returns:
        d_mean = sum(d_returns) / len(d_returns)
        d_var = sum((x - d_mean)**2 for x in d_returns) / max(len(d_returns) - 1, 1)
        d_vol = math.sqrt(d_var) * math.sqrt(252) * 100

    d_peak = decade_rows[0]['close']
    d_max_dd = 0
    for r in decade_rows:
        if r['close'] > d_peak:
            d_peak = r['close']
        dd = (r['close'] - d_peak) / d_peak
        if dd < d_max_dd:
            d_max_dd = dd

    d_high = max(r['close'] for r in decade_rows)
    d_low = min(r['close'] for r in decade_rows)
    d_divs = sum(r['dividend'] for r in decade_rows)

    decades[label] = {
        'start_price': d_first,
        'end_price': d_last,
        'total_return': d_return,
        'cagr': d_cagr,
        'volatility': d_vol,
