        yearly_vol[r['date'].year].append(r['volume'])

yearly_vol_avg = {}
for y, vols in sorted(yearly_vol.items()):
    yearly_vol_avg[y] = sum(vols) / len(vols)

# Annual dividend totals
yearly_divs = defaultdict(float)
for r in rows:
    yearly_divs[r['date'].year] += r['dividend']

# Stock splits
splits = [(r['date_str'], r['split']) for r in rows if r['split'] != 0.0]

# Sub-period CAGRs
def compute_cagr(data, start_year, end_year):
    subset = [r for r in data if start_year <= r['date'].year <= end_year]
    if len(subset) < 2:
        return None
    s = subset[0]['close']
    e = subset[-1]['close']
    y = (subset[-1]['date'] - subset[0]['date']).days / 365.25
    if y < 0.5 or s <= 0:
        return None
    return (pow(e / s, 1.0 / y) - 1) * 100

sub_cagrs = {
    '1972–1982': compute_cagr(rows, 1972, 1982),
    '1982–1992': compute_cagr(rows, 1982, 1992),
    '1992–2002': compute_cagr(rows, 1992, 2002),
    '2002–2012': compute_cagr(rows, 2002, 2012),
    '2012–2022': compute_cagr(rows, 2012, 2022),
    '2022–2026': compute_cagr(rows, 2022, 2026),
}

# ── Rolling 1-year volatility for chart ───────────────────────────────────
rolling_vol_dates = []
rolling_vol_values = []
window = 252
for i in range(window, len(daily_returns)):
    segment = daily_returns[i-window:i]
    m = sum(segment) / window
    v = sum((x - m)**2 for x in segment) / (window - 1)
    rolling_vol_dates.append(rows[i+1]['date'].strftime('%Y-%m'))
    rolling_vol_values.append(math.sqrt(v) * math.sqrt(252) * 100)

# Downsample rolling vol to monthly
rv_monthly = {}
for d, v in zip(rolling_vol_dates, rolling_vol_values):
    rv_monthly[d] = v
rv_dates = sorted(rv_monthly.keys())
rv_vals = [rv_monthly[d] for d in rv_dates]

