import csv
import math
from datetime import datetime
from collections import defaultdict

# ── Load data ──────────────────────────────────────────────────────────────
rows = []
with open('/app/benchmark/data.csv') as f:
    reader = csv.DictReader(f)
    for r in reader:
        date_str = r['Date'][:10]
        dt = datetime.strptime(date_str, '%Y-%m-%d')
        rows.append({
            'date': dt,
            'date_str': date_str,
            'open': float(r['Open']),
            'high': float(r['High']),
            'low': float(r['Low']),
            'close': float(r['Close']),
            'volume': int(r['Volume']),
            'dividend': float(r['Dividends']),
            'split': float(r['Stock Splits']),
        })

rows.sort(key=lambda x: x['date'])

# ── Basic facts ──────────────────────────────────────────────────────────────
first_date = rows[0]['date']
last_date = rows[-1]['date']
first_close = rows[0]['close']
last_close = rows[-1]['close']
total_days = len(rows)
years = (last_date - first_date).days / 365.25

# KPIs
cumulative_return = (last_close / first_close - 1) * 100
cagr = (pow(last_close / first_close, 1.0 / years) - 1) * 100

# Max Drawdown
peak = rows[0]['close']
max_dd = 0
max_dd_peak_date = rows[0]['date_str']
max_dd_trough_date = rows[0]['date_str']
dd_peak_date = rows[0]['date_str']
drawdowns = []
current_dd_start = rows[0]['date_str']

for r in rows:
    if r['close'] > peak:
        peak = r['close']
        dd_peak_date = r['date_str']
    dd = (r['close'] - peak) / peak
    if dd < max_dd:
        max_dd = dd
        max_dd_peak_date = dd_peak_date
        max_dd_trough_date = r['date_str']

max_dd_pct = max_dd * 100

# Annualized Volatility
daily_returns = []
for i in range(1, len(rows)):
    if rows[i-1]['close'] > 0:
        ret = (rows[i]['close'] - rows[i-1]['close']) / rows[i-1]['close']
        daily_returns.append(ret)

mean_ret = sum(daily_returns) / len(daily_returns)
variance = sum((r - mean_ret)**2 for r in daily_returns) / (len(daily_returns) - 1)
daily_vol = math.sqrt(variance)
ann_vol = daily_vol * math.sqrt(252) * 100

# Total Dividends
total_dividends = sum(r['dividend'] for r in rows)

# All-time high/low
ath = max(rows, key=lambda x: x['close'])
atl = min(rows, key=lambda x: x['close'])

# ── Identify major drawdown episodes ──────────────────────────────────────
def find_drawdowns(data, top_n=5):
    episodes = []
    peak_val = data[0]['close']
    peak_idx = 0
    current_trough = data[0]['close']
    trough_idx = 0
    in_drawdown = False

    for i, r in enumerate(data):
        if r['close'] >= peak_val:
            if in_drawdown and (current_trough / peak_val - 1) < -0.15:
                episodes.append({
                    'peak_date': data[peak_idx]['date_str'],
                    'trough_date': data[trough_idx]['date_str'],
                    'peak_val': peak_val,
                    'trough_val': current_trough,
                    'drawdown': (current_trough / peak_val - 1) * 100,
                    'recovery_date': r['date_str'],
                })
            peak_val = r['close']
            peak_idx = i
            current_trough = r['close']
            trough_idx = i
            in_drawdown = False
        elif r['close'] < current_trough:
            current_trough = r['close']
            trough_idx = i
            in_drawdown = True

    if in_drawdown and (current_trough / peak_val - 1) < -0.15:
        episodes.append({
            'peak_date': data[peak_idx]['date_str'],
            'trough_date': data[trough_idx]['date_str'],
            'peak_val': peak_val,
            'trough_val': current_trough,
            'drawdown': (current_trough / peak_val - 1) * 100,
            'recovery_date': 'N/A',
        })

    episodes.sort(key=lambda x: x['drawdown'])
    return episodes[:top_n]

major_drawdowns = find_drawdowns(rows, 7)

# ── Decade-by-decade analysis ─────────────────────────────────────────────
decades = {}
for decade_start in range(1970, 2030, 10):
    decade_end = decade_start + 10
    label = f"{decade_start}s"
    decade_rows = [r for r in rows if decade_start <= r['date'].year < decade_end]
    if not decade_rows:
        continue

    d_first = decade_rows[0]['close']
    d_last = decade_rows[-1]['close']
    d_return = (d_last / d_first - 1) * 100
    d_years = max((decade_rows[-1]['date'] - decade_rows[0]['date']).days / 365.25, 0.5)
    d_cagr = (pow(d_last / d_first, 1.0 / d_years) - 1) * 100

    d_returns = []
    for i in range(1, len(decade_rows)):
        if decade_rows[i-1]['close'] > 0:
            d_returns.append((decade_rows[i]['close'] - decade_rows[i-1]['close']) / decade_rows[i-1]['close'])

    d_vol = 0
    if d_returns:
        d_mean = sum(d_returns) / len(d_returns)
        d_var = sum((x - d_mean)**2 for x in d_returns) / max(len(d_returns) - 1, 1)
        d_vol = math.sqrt(d_var) * math.sqrt(252) * 100

    d_peak = decade_rows[0]['close']
    d_max_dd = 0
    for r in decade_rows:
        if r['close'] > d_peak:
            d_peak = r['close']
        dd = (r['close'] - d_peak) / d_peak
        if dd < d_max_dd:
            d_max_dd = dd

    d_high = max(r['close'] for r in decade_rows)
    d_low = min(r['close'] for r in decade_rows)
    d_divs = sum(r['dividend'] for r in decade_rows)

    decades[label] = {
        'start_price': d_first,
        'end_price': d_last,
        'total_return': d_return,
        'cagr': d_cagr,
        'volatility': d_vol,
        'max_drawdown': d_max_dd * 100,
        'high': d_high,
        'low': d_low,
        'dividends': d_divs,
        'trading_days': len(decade_rows),
    }

# ── Bull/Bear phases ──────────────────────────────────────────────────────
# Identify major phases using 200-day moving average crossovers simplified
# We'll use a simpler approach: significant peaks and troughs
def identify_phases(data, threshold=0.30):
    phases = []
    peak = data[0]['close']
    trough = data[0]['close']
    peak_date = data[0]['date_str']
    trough_date = data[0]['date_str']
    in_bull = True
    last_pivot_date = data[0]['date_str']
    last_pivot_price = data[0]['close']

    for r in data:
        if in_bull:
            if r['close'] > peak:
                peak = r['close']
                peak_date = r['date_str']
            elif (r['close'] - peak) / peak < -threshold:
                phases.append({'type': 'Bull', 'start': last_pivot_date, 'end': peak_date,
                             'start_price': last_pivot_price, 'end_price': peak,
                             'return': (peak / last_pivot_price - 1) * 100})
                in_bull = False
                trough = r['close']
                trough_date = r['date_str']
                last_pivot_date = peak_date
                last_pivot_price = peak
        else:
            if r['close'] < trough:
                trough = r['close']
                trough_date = r['date_str']
            elif (r['close'] - trough) / trough > threshold:
                phases.append({'type': 'Bear', 'start': last_pivot_date, 'end': trough_date,
                             'start_price': last_pivot_price, 'end_price': trough,
                             'return': (trough / last_pivot_price - 1) * 100})
                in_bull = True
                peak = r['close']
                peak_date = r['date_str']
                last_pivot_date = trough_date
                last_pivot_price = trough

    phases.append({'type': 'Bull' if in_bull else 'Bear', 'start': last_pivot_date, 'end': data[-1]['date_str'],
                 'start_price': last_pivot_price, 'end_price': data[-1]['close'],
                 'return': (data[-1]['close'] / last_pivot_price - 1) * 100})
    return phases

phases = identify_phases(rows, 0.25)

# ── Prepare chart data ────────────────────────────────────────────────────
# Monthly close prices for the main chart (reduce data points)
monthly = {}
for r in rows:
    key = r['date'].strftime('%Y-%m')
    monthly[key] = r['close']

monthly_dates = sorted(monthly.keys())
monthly_closes = [monthly[d] for d in monthly_dates]

# Yearly volume averages
yearly_vol = defaultdict(list)
for r in rows:
    if r['volume'] > 0:
        yearly_vol[r['date'].year].append(r['volume'])

yearly_vol_avg = {}
for y, vols in sorted(yearly_vol.items()):
    yearly_vol_avg[y] = sum(vols) / len(vols)

# Annual dividend totals
yearly_divs = defaultdict(float)
for r in rows:
    yearly_divs[r['date'].year] += r['dividend']

# Stock splits
splits = [(r['date_str'], r['split']) for r in rows if r['split'] != 0.0]

# Sub-period CAGRs
def compute_cagr(data, start_year, end_year):
    subset = [r for r in data if start_year <= r['date'].year <= end_year]
    if len(subset) < 2:
        return None
    s = subset[0]['close']
    e = subset[-1]['close']
    y = (subset[-1]['date'] - subset[0]['date']).days / 365.25
    if y < 0.5 or s <= 0:
        return None
    return (pow(e / s, 1.0 / y) - 1) * 100

sub_cagrs = {
    '1972–1982': compute_cagr(rows, 1972, 1982),
    '1982–1992': compute_cagr(rows, 1982, 1992),
    '1992–2002': compute_cagr(rows, 1992, 2002),
    '2002–2012': compute_cagr(rows, 2002, 2012),
    '2012–2022': compute_cagr(rows, 2012, 2022),
    '2022–2026': compute_cagr(rows, 2022, 2026),
}

# ── Rolling 1-year volatility for chart ───────────────────────────────────
rolling_vol_dates = []
rolling_vol_values = []
window = 252
for i in range(window, len(daily_returns)):
    segment = daily_returns[i-window:i]
    m = sum(segment) / window
    v = sum((x - m)**2 for x in segment) / (window - 1)
    rolling_vol_dates.append(rows[i+1]['date'].strftime('%Y-%m'))
    rolling_vol_values.append(math.sqrt(v) * math.sqrt(252) * 100)

# Downsample rolling vol to monthly
rv_monthly = {}
for d, v in zip(rolling_vol_dates, rolling_vol_values):
    rv_monthly[d] = v
rv_dates = sorted(rv_monthly.keys())
rv_vals = [rv_monthly[d] for d in rv_dates]

# ── Drawdown series for chart ─────────────────────────────────────────────
dd_series_dates = []
dd_series_vals = []
peak_for_dd = rows[0]['close']
for r in rows:
    if r['close'] > peak_for_dd:
        peak_for_dd = r['close']
    dd_val = (r['close'] - peak_for_dd) / peak_for_dd * 100
    dd_series_dates.append(r['date'].strftime('%Y-%m-%d'))
    dd_series_vals.append(round(dd_val, 2))

# Downsample drawdown to weekly
dd_weekly_dates = dd_series_dates[::5]
dd_weekly_vals = dd_series_vals[::5]

# ── Annual returns for bar chart ──────────────────────────────────────────
yearly_prices = {}
for r in rows:
    y = r['date'].year
    if y not in yearly_prices:
        yearly_prices[y] = {'first': r['close'], 'last': r['close']}
    yearly_prices[y]['last'] = r['close']

annual_returns = {}
for y in sorted(yearly_prices.keys()):
    fp = yearly_prices[y]['first']
    lp = yearly_prices[y]['last']
    if fp > 0:
        annual_returns[y] = (lp / fp - 1) * 100

# ── Dividend yield over time ──────────────────────────────────────────────
yearly_div_yield = {}
for y in sorted(yearly_divs.keys()):
    if y in yearly_prices and yearly_prices[y]['last'] > 0:
        yearly_div_yield[y] = (yearly_divs[y] / yearly_prices[y]['last']) * 100

# ── Generate HTML ─────────────────────────────────────────────────────────
def fmt(val, decimals=2):
    if val is None:
        return 'N/A'
    return f"{val:,.{decimals}f}"

def fmt_pct(val, decimals=2):
    if val is None:
        return 'N/A'
    return f"{val:+.{decimals}f}%" if val >= 0 else f"{val:.{decimals}f}%"

def fmt_price(val):
    return f"${val:,.2f}"

# Drawdown table rows
dd_rows_html = ""
for i, dd in enumerate(major_drawdowns):
    label = ""
    if "2008" in dd['peak_date'] or "2009" in dd['trough_date'] or "2007" in dd['peak_date']:
        label = "Global Financial Crisis"
    elif "2020" in dd['trough_date']:
        label = "COVID-19 Crash"
    elif "2000" in dd['peak_date'] or "2001" in dd['trough_date'] or "2002" in dd['trough_date']:
        label = "Dot-Com / Post-9/11"
    elif "1973" in dd['peak_date'] or "1974" in dd['trough_date']:
        label = "Oil Crisis / Bear Market"
    elif "1987" in dd['trough_date']:
        label = "Black Monday"
    elif "2022" in dd['trough_date'] or "2022" in dd['peak_date']:
        label = "2022 Market Downturn"
    elif "2025" in dd['peak_date'] or "2026" in dd['trough_date'] or "2025" in dd['trough_date']:
        label = "2025–2026 Correction"
    elif "1998" in dd['trough_date']:
